import argparse,hashlib,json,posixpath,shutil,subprocess,zipfile,xml.etree.ElementTree as E
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--input',type=Path,required=True);p.add_argument('--officecli',required=True);p.add_argument('--outdir',type=Path,required=True);a=p.parse_args()
if a.outdir.exists():raise FileExistsError(a.outdir)
a.outdir.mkdir(parents=True);ns={'p':'http://schemas.openxmlformats.org/presentationml/2006/main','a':'http://schemas.openxmlformats.org/drawingml/2006/main','a14':'http://schemas.microsoft.com/office/drawing/2010/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
with zipfile.ZipFile(a.input) as z:
 s=E.fromstring(z.read('ppt/slides/slide2.xml'));blip=s.find('.//p:pic/p:blipFill/a:blip',ns);effect=blip.find('.//a14:artisticBlur',ns)
 if effect is None or effect.get('radius')!='30':raise RuntimeError('Expected real native artistic Blur30 provenance')
 rels={r.get('Id'):r.get('Target') for r in E.fromstring(z.read('ppt/slides/_rels/slide2.xml.rels'))};rid=blip.get('{'+ns['r']+'}embed');target=rels[rid];part=target.lstrip('/') if target.startswith('/') else posixpath.normpath('ppt/slides/'+target);data=z.read(part)
 if not data.startswith(b'\x89PNG'):raise RuntimeError('Expected native PNG cache, never render another image externally')
 cache=a.outdir/'powerpoint-native-blur-cache.png';cache.write_bytes(data)
 original=E.fromstring(z.read('ppt/slides/slide1.xml')).find('.//p:pic/p:blipFill/a:blip',ns);orig_rels={r.get('Id'):r.get('Target') for r in E.fromstring(z.read('ppt/slides/_rels/slide1.xml.rels'))};orig_target=orig_rels[original.get('{'+ns['r']+'}embed')];orig_part=orig_target.lstrip('/') if orig_target.startswith('/') else posixpath.normpath('ppt/slides/'+orig_target);original_data=z.read(orig_part);original_file=a.outdir/'unchanged-original.png';original_file.write_bytes(original_data)
deck=a.outdir/'local-blur.pptx';shutil.copy2(a.input,deck)
def cli(*args):
 r=subprocess.run([a.officecli,*map(str,args)],capture_output=True,text=True,encoding='utf-8')
 if r.returncode:raise RuntimeError(r.stdout+r.stderr)
 return r.stdout
cli('open',deck)
for s in [3,4]:
 cli('set',deck,f'/slide[{s}]','--prop','background=image:'+str(cache.resolve()),'--json')
 # Native PowerPoint deduplicates the background and foreground relationship. CLI
 # background replacement can remove that shared rId; explicitly rebind the clear
 # foreground to the unchanged original bytes, then validate all references.
 cli('set',deck,f'/slide[{s}]/picture[@name=clear-foreground]','--prop','src='+str(original_file.resolve()),'--json')
