(a.outdir/'native-cache-provenance.json').write_text(json.dumps({'sourcePresentationSHA256':hashlib.sha256(a.input.read_bytes()).hexdigest(),'sourcePart':part,'nativeEffect':'a14:artisticBlur','nativeRadius':30,'cacheSHA256':hashlib.sha256(data).hexdigest(),'method':'Copy exact PNG cache authored by PowerPoint native PictureEffects; no external blur engine. Editable native blur picture and unchanged original remain in presentation; slide background is a snapshot that is regenerated by rerunning native polish+bridge.'},indent=2),encoding='utf-8')
